<?php
/** Pages atomic HTML/data editor with individual metadata; native layout data stays preserved behind the advanced editor. */
declare(strict_types=1);
use function DBLESSCMS\e;
$isNew=$route==='new';$composePage=$isNew?null:$context->store->read($key)['data'];$composeCore=new \DBLESSCMS\Language();$composeCore->select($context->language->locale());
$markupDefinition=$composePage['markup']??['html'=>'','bindings'=>[]];$markupPageKey=$isNew?'starter-page':$key;
?>
<form method="post" action="<?= e($context->url($isNew?'compose-create':'markup-save')) ?>" data-pages-form data-page-markup-form class="stack">
<input type="hidden" name="compose" value="1"><input type="hidden" name="key" value="<?= e($key) ?>"><input type="hidden" name="revision" value="<?= e($revision) ?>"><input type="hidden" name="site_revision" value="<?= e($context->store->read('site')['revision']) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>">
<section class="panel"><h2><?= e($composeCore->text('custom.authoring')) ?></h2><div class="field-grid">
<?php if($isNew): ?><label><?= e($t('pages.slug')) ?><input name="slug" pattern="[a-z0-9][a-z0-9\-]{0,63}" maxlength="64" required></label><label><?= e($t('pages.model')) ?><select name="model"><?php foreach($pages as $slug=>$item): if(in_array((string)$slug,['home','404'],true))continue; ?><option value="<?= e($slug) ?>" <?= $slug==='starter-page'?'selected':'' ?>><?= e($item['data']['meta']['title']) ?></option><?php endforeach; ?></select></label><?php endif; ?>
<label><?= e($t('catalog.status')) ?><select name="page_status"><?php foreach(['draft','published'] as $status): ?><option value="<?= e($status) ?>" <?= ($composePage['status']??'draft')===$status?'selected':'' ?>><?= e($t('status.'.$status)) ?></option><?php endforeach; ?></select></label></div></section>
<section class="panel"><h2><?= e($t('pages.metadata')) ?></h2><div class="field-grid"><?php foreach(['title','description','keywords','image','imageAlt'] as $field): ?><label><?= e($t('pages.meta_'.$field)) ?><?php if($field==='description'): ?><textarea name="meta_<?= e($field) ?>" maxlength="500" rows="3" required><?= e($composePage['meta'][$field]??'') ?></textarea><?php else: ?><input name="meta_<?= e($field) ?>" maxlength="<?= $field==='title'?200:2048 ?>" value="<?= e($composePage['meta'][$field]??'') ?>" <?= $field==='title'?'required':'' ?>><?php endif; ?></label><?php endforeach; ?></div></section>
<section class="panel"><?php if($isNew): ?><input type="hidden" name="markup_enabled" value="1"><?php else: ?><label class="editor-checkbox"><input type="checkbox" name="markup_enabled" value="1" <?= isset($composePage['markup'])?'checked':'' ?>><?= e($composeCore->text('markup.pageEnable')) ?></label><p class="muted"><?= e($composeCore->text('markup.native')) ?></p><?php endif; ?><?php require $context->config->root.'/admin/markup-editor.php'; ?></section><div class="savebar"><button class="button-primary" type="submit"><?= e($t($isNew?'pages.composeCreate':'editor.save')) ?></button></div></form>
